const body = $input.first().json.body;
const required = ['org_name', 'project_title', 'funder_name', 'funding_amount_requested', 'project_description'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const amount = parseFloat(body.funding_amount_requested);
if (isNaN(amount) || amount <= 0) return [{ json: { valid: false, error: 'funding_amount_requested must be a positive number' } }];
const grantTypes = ['federal', 'state', 'foundation', 'corporate', 'community', 'research', 'arts', 'education', 'health', 'other'];
const grantType = grantTypes.includes(body.grant_type) ? body.grant_type : 'foundation';
return [{ json: {
  valid: true,
  orgName: body.org_name.trim(),
  orgDescription: (body.org_description || '').slice(0, 600),
  orgType: body.org_type || 'nonprofit',
  projectTitle: body.project_title.trim(),
  projectDescription: body.project_description.trim().slice(0, 2000),
  funderName: body.funder_name.trim(),
  funderPriorities: (body.funder_priorities || '').slice(0, 600),
  grantType,
  fundingAmountRequested: amount,
  currency: body.currency || 'USD',
  projectDuration: body.project_duration || '12 months',
  targetPopulation: (body.target_population || '').slice(0, 400),
  expectedOutcomes: (body.expected_outcomes || '').slice(0, 600),
  previousFunding: body.previous_funding || '',
  section: body.section || 'full_narrative',
  wordLimit: parseInt(body.word_limit) || null,
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const search = $('Research Funder').first().json;
const input = $('Validate Input').first().json;
const funderContext = (search.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
return [{ json: { input, funderContext: funderContext || 'No funder context found — use provided priorities.' } }];

values.content:
Write a grant application section.

Organization: {{ $json.input.orgName }} ({{ $json.input.orgType }})
Org description: {{ $json.input.orgDescription || 'not provided' }}
Project title: {{ $json.input.projectTitle }}
Project description: {{ $json.input.projectDescription }}
Funder: {{ $json.input.funderName }} ({{ $json.input.grantType }} grant)
Funder priorities (provided): {{ $json.input.funderPriorities || 'none provided' }}
Amount requested: {{ $json.input.currency }}{{ $json.input.fundingAmountRequested.toLocaleString() }}
Project duration: {{ $json.input.projectDuration }}
Target population: {{ $json.input.targetPopulation || 'not specified' }}
Expected outcomes: {{ $json.input.expectedOutcomes || 'not specified' }}
Previous funding from this funder: {{ $json.input.previousFunding || 'none' }}
Section requested: {{ $json.input.section }}
Word limit: {{ $json.input.wordLimit ? $json.input.wordLimit + ' words' : 'no limit specified' }}

Funder research context:
{{ $json.funderContext }}

Return this JSON:
{
  "alignment_analysis": "2-3 sentences on how this project aligns with this funder's priorities — be specific about the match",
  "sections": {
    "executive_summary": "150-200 word compelling overview — problem, solution, population served, outcomes, amount requested. Write this last but put it first.",
    "statement_of_need": "Establish the problem with data. 250-400 words. Start with the problem, not the organization. Use specific statistics. Connect to funder priorities.",
    "project_description": "Describe the project activities clearly. 400-600 words. Who does what, when, how, for whom. Include a clear logic model narrative.",
    "organizational_capacity": "100-200 words demonstrating the org can actually do this. Track record, staff expertise, partnerships.",
    "evaluation_plan": "150-250 words. How will you know if it worked? Specific metrics, data collection methods, who evaluates.",
    "budget_narrative": "100-200 words justifying the request. Not line items but the rationale for why this amount is needed and appropriate."
  },
  "requested_section_only": "if section is not full_narrative, return only the requested section here as the primary output — otherwise null",
  "red_flag_check": ["any weaknesses in the application as submitted — things reviewers might push back on"],
  "strengthening_suggestions": ["2-3 specific additions or changes that would strengthen this application before submission"],
  "funder_language_to_use": ["3-5 specific phrases or terms from the funder's materials that should appear in the application"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let grant;
try { grant = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
grant._meta = { orgName: input.orgName, projectTitle: input.projectTitle, funderName: input.funderName, amount: input.fundingAmountRequested, currency: input.currency, section: input.section, replyEmail: input.replyEmail };
return [{ json: grant }];

const g = $input.first().json;
const m = g._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const sectionTitles = {
  executive_summary: 'Executive Summary',
  statement_of_need: 'Statement of Need',
  project_description: 'Project Description',
  organizational_capacity: 'Organizational Capacity',
  evaluation_plan: 'Evaluation Plan',
  budget_narrative: 'Budget Narrative'
};

const sections = g.sections || {};
const sectionBlocks = Object.entries(sectionTitles).map(([key, title]) => {
  const content = sections[key];
  if (!content) return '';
  return `<div style="margin-bottom:28px">
    <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#374151;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-bottom:12px">${esc(title)}</div>
    <div style="font-size:15px;line-height:1.8;color:#1a1a1a;white-space:pre-wrap">${esc(content)}</div>
  </div>`;
}).join('');

const redFlags = (g.red_flag_check||[]).map(rf => `<div style="font-size:14px;color:#7f1d1d;padding:5px 0;border-bottom:1px solid #fecaca">⚠ ${esc(rf)}</div>`).join('');
const suggestions = (g.strengthening_suggestions||[]).map(s => `<li style="font-size:14px;margin-bottom:7px;line-height:1.55;color:#374151">${esc(s)}</li>`).join('');
const funderLang = (g.funder_language_to_use||[]).map(l => `<span style="display:inline-block;background:#dbeafe;color:#1e40af;font-size:12px;padding:3px 10px;border-radius:12px;margin:3px 4px 3px 0">${esc(l)}</span>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f4f0;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1a2744;color:#fff;padding:22px 32px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#7b92c4;margin-bottom:5px">Grant Application · ${esc(m.funderName)}</div>
    <div style="font-size:20px;font-weight:700;line-height:1.3">${esc(m.projectTitle)}</div>
    <div style="font-size:14px;color:#7b92c4;margin-top:4px">${esc(m.orgName)} · ${m.currency}${m.amount.toLocaleString()} requested</div>
  </div>

  <div style="background:#eff6ff;padding:14px 32px;border:1px solid #bfdbfe;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">Alignment with funder</div>
    <p style="font-size:14px;line-height:1.7;color:#1e3a8a;margin:0">${esc(g.alignment_analysis)}</p>
  </div>

  <div style="background:#fff;padding:28px 32px;border:1px solid #e5e7eb;border-top:none">
    ${m.section !== 'full_narrative' && g.requested_section_only
      ? `<div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#374151;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-bottom:16px">${esc(sectionTitles[m.section] || m.section)}</div>
         <div style="font-size:15px;line-height:1.8;color:#1a1a1a;white-space:pre-wrap">${esc(g.requested_section_only)}</div>`
      : sectionBlocks}
  </div>

  ${funderLang ? `<div style="background:#fff;padding:14px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f4f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Use this funder's language</div>
    <div>${funderLang}</div>
  </div>` : ''}

  ${redFlags ? `<div style="background:#fef2f2;padding:14px 32px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:8px">Potential weaknesses — address before submitting</div>
    ${redFlags}
  </div>` : ''}

  ${suggestions ? `<div style="background:#fff;padding:14px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f4f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Strengthening suggestions</div>
    <ul style="padding-left:18px;margin:0">${suggestions}</ul>
  </div>` : ''}

  <div style="background:#1a2744;color:#3d5a99;font-size:11px;padding:12px 32px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Grant Writing Assistant · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, projectTitle: m.projectTitle, funderName: m.funderName, grant: g } }];
